            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
        }
    });
    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
    ui.label(theme::meta_text(
        ui,
        format!("Key {}", short_hash(&identity.spki_sha256)),
