/// The invite from the scanned or pasted text: the URL the host's
/// QR holds (`https://host:port/#code=…&key=…&id=…`), or the JSON an
/// older host printed.
public static func parse(_ text: String) throws -> PairingInvite {
    let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.hasPrefix("https://") else {
        return try Wire.decode(PairingInvite.self, from: Data(trimmed.utf8))
    }
    guard let components = URLComponents(string: trimmed),
          let host = components.host,
          let fragment = components.fragment
    else {
        throw DecodingError.dataCorrupted(
            .init(codingPath: [], debugDescription: "the invite URL has no fragment"))
    }
    var fields: [String: String] = [:]
    for pair in fragment.split(separator: "&") {
        let parts = pair.split(separator: "=", maxSplits: 1).map(String.init)
        if parts.count == 2 { fields[parts[0]] = parts[1] }
    }
    guard let code = fields["code"], !code.isEmpty,
          let key = fields["key"], let id = fields["id"]
    else {
        throw DecodingError.dataCorrupted(
            .init(codingPath: [], debugDescription: "the invite URL lacks code, key or id"))
    }
    let address = components.port.map { "\(host):\($0)" } ?? host
    return PairingInvite(
        serverID: ServerID(id), spkiSha256: key, code: code, addresses: [address])
}

