* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.4 -apple-system, system-ui, sans-serif;
}

header {
  display: flex;
  justify-content: space-between;
