  border-radius: 8px;
  background: var(--card);
  font: 13px/1.4 ui-monospace, Menlo, monospace;
}

textarea {
  display: block;
  width: 100%;
  min-height: 96px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  color: inherit;
  font: inherit;
}

button {
  padding: 8px 14px;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: var(--bg);
  font: inherit;
}

button.plain {
  background: transparent;
  color: var(--accent);
}

.notice {
  margin: 12px 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
}

.actions {
  display: flex;
  gap: 8px;
  margin: 8px 0;
}

