        t,
    );
    assert_eq!(status, 200, "{page}");
    let body = &page["body"];
    assert_eq!(body["title"], "explain-repo");
    assert_eq!(body["total"], 3);
    assert_eq!(body["from"], 1);
    assert_eq!(body["next"], 3);
