    assert_eq!(rest["revision"], revision, "one conversation, one revision");
    let (_, last_page) = get(
        &mut port,
        &format!("/api/v1/sessions/{session}/conversation?from=last&limit=1"),
        t,
    );
    assert_eq!(last_page["body"]["from"], 3);

    let (status, last) = get(
