/// The embedded editor's prompt field.
fn prompt_field<'h>(harness: &'h mut Harness<'static, SwitchboardApp>) -> egui_kittest::Node<'h> {
    harness.get_by_role_and_label(Role::MultilineTextInput, "Prompt")
}

