/// A ticket's page with `edit` applied to Orchard's ticket first.
fn ticket_page(
    edit: impl FnOnce(&mut switchboard::ports::dispatch::TicketView),
) -> Harness<'static, SwitchboardApp> {
    ticket_page_on(FakeDispatch::default(), Changes::default(), edit)
}

/// `ticket_page_built` in the default 1200×900 window.
fn ticket_page_on(
    dispatch: FakeDispatch,
    changes: Changes,
    edit: impl FnOnce(&mut switchboard::ports::dispatch::TicketView),
) -> Harness<'static, SwitchboardApp> {
    ticket_page_built(
        dispatch,
        FakeChanges {
            changes,
            ..FakeChanges::default()
        },
        egui::vec2(1200.0, 900.0),
        edit,
    )
}

/// `ticket_page` in a window of `size`.
fn ticket_page_sized(
    size: egui::Vec2,
    edit: impl FnOnce(&mut switchboard::ports::dispatch::TicketView),
) -> Harness<'static, SwitchboardApp> {
    ticket_page_built(FakeDispatch::default(), FakeChanges::default(), size, edit)
}

/// `ticket_page` against a runner that answers with the same status,
/// with `dispatch`'s events and paths, and a branch with `changes`, in a
/// window of `size`. The page's first reads and their replies are
/// cleared before a test looks; it asks again only when the ticket's
/// `updated_ms` changes.
fn ticket_page_built(
    mut dispatch: FakeDispatch,
    changes: FakeChanges,
    size: egui::Vec2,
    edit: impl FnOnce(&mut switchboard::ports::dispatch::TicketView),
) -> Harness<'static, SwitchboardApp> {
    let mut status = dispatch_status();
    status.tickets[0].decisions.clear();
    status.tickets[0].tree = Some("/wt/t1".into());
    edit(&mut status.tickets[0]);
    dispatch.status = Some(status.clone());
    let services = Services {
        dispatch: Some(Box::new(dispatch)),
        changes: Arc::new(changes),
        ..fake_services(
            FakeOpener::default(),
            FakeSecrets::default(),
            FakeHost::default(),
        )
    };
    let (mut harness, _) = harness_sized(services, size);
    harness
        .state_mut()
        .dispatch(AppAction::DispatchStatus(Some(status)));
    harness
        .state_mut()
        .dispatch(AppAction::ShowTicket("t1".into()));
    harness.run_steps(2);
    harness.state_mut().dispatched.clear();
    harness
}

/// The Dispatch page with a supervisor session `edit`ed into beta's
/// project: Orchard has a `[supervisor]` table whose session is that
/// record, PTA has none.
fn supervised_page(
    edit: impl FnOnce(&mut SessionRecord),
) -> (Harness<'static, SwitchboardApp>, RecordId) {
    let (mut harness, ids) = harness();
    let mut sup = record(
        ids.beta,
        "Supervisor · Orchard",
        SessionKind::Agent(AgentKind::ClaudeCode),
        1,
    );
    sup.resume = Some(ResumeHandle::ClaudeCode {
        session_id: uuid::Uuid::nil(),
        transcript: Some(PathBuf::from("/nowhere/x.jsonl")),
    });
    edit(&mut sup);
    let id = sup.id;
    let core = harness.state_mut().core_mut_for_seeding();
    let mut workspaces = core.workspaces().to_vec();
    workspaces
        .iter_mut()
        .find(|w| w.project.id == ids.beta)
        .unwrap()
        .sessions
        .push(sup);
    core.seed(workspaces, vec![]);
    let mut status = dispatch_status();
    status.projects[0].supervisor = Some(switchboard::ports::dispatch::SupervisorView {
        session: Some(id.0.to_string()),
        created_ms: 1,
        ..Default::default()
    });
    harness
        .state_mut()
        .dispatch(AppAction::DispatchStatus(Some(status)));
    harness.state_mut().dispatch(AppAction::ShowDispatch);
    harness.run_steps(2);
    harness.state_mut().dispatched.clear();
    (harness, id)
}

/// One chip, on the project with the table: it says what the session
