    harness.state_mut().dispatched.clear();
    click(&mut harness, "Resume supervisor");
    assert_eq!(actions(&harness), [AppAction::ReturnToSession(id)]);
    harness.state_mut().dispatched.clear();
    click(&mut harness, "Fresh supervisor");
