        harness.state().ui_state.confirm_close_ticket.as_deref(),
        Some("t1"),
        "shown in the Dispatch window"
    );
    harness.state_mut().dispatch(AppAction::CloseDispatchWindow);
    harness.run_steps(2);
    assert!(harness.state().ui_state.confirm_close_ticket.is_none());
}

