                message: Some("being rewritten".into()),
                message_session: Some(ids.server.0.to_string()),
                ..RewriteView::default()
            },
        ),
        attempt(
            3,
            "complete",
            RewriteView {
                message: Some("kept as written".into()),
                ..RewriteView::default()
            },
        ),
        attempt(
            4,
            "complete",
            RewriteView {
                message: Some("rewritten, bbbbbbb → ccccccc".into()),
                message_head: Some("cccccccc3333".into()),
                ..RewriteView::default()
            },
        ),
        attempt(
