/// The Dispatch page lists what waits on the user with its options as
/// buttons, and the rail row counts it; a click is one decide action.
#[test]
fn dispatch_page_answers_a_decision_with_a_click() {
    let (mut harness, _) = harness();
    harness
        .state_mut()
        .dispatch(AppAction::DispatchStatus(Some(dispatch_status())));
    harness.state_mut().dispatched.clear();
    harness.run_steps(2);
    click(&mut harness, "Dispatch");
    assert!(actions(&harness).contains(&AppAction::ShowDispatch));
    harness.get_by_label("Which lanes does #104 need?");
    // Narrowed to another project, Orchard's decision and tickets go.
    // The chip comes before the project's own section heading.
    harness
        .query_all_by_label("PTA")
        .next()
        .expect("the PTA chip")
        .click();
    harness.run_steps(2);
    assert!(
        harness
            .query_by_label("Which lanes does #104 need?")
            .is_none()
    );
    assert!(harness.query_by_label("#104 One file per entry").is_none());
    harness.get_by_label("#9 Roster import");
    click(&mut harness, "All");
    // A decision that takes several lanes: ticks, then one Answer, with
    // the suggested lane ticked to begin with and nothing sent by a tick.
    click(&mut harness, "backend");
    assert!(
        !actions(&harness)
            .iter()
            .any(|a| matches!(a, AppAction::DispatchDecide { .. })),
        "a tick is not an answer"
    );
    click(&mut harness, "Answer: backend, frontend");
    assert!(actions(&harness).contains(&AppAction::DispatchDecide {
        ticket: "t1".into(),
        decision: "d1".into(),
        answer: "backend,frontend".into(),
        note: None,
    }));
    // The title is a link in the decision card and in the project's list.
    harness
        .query_all_by_label("#104 One file per entry")
        .next()
        .expect("the ticket's link")
        .click();
    harness.run_steps(2);
    assert!(actions(&harness).contains(&AppAction::ShowTicket("t1".into())));
    assert_eq!(harness.state().core().view(), View::Ticket("t1".into()));
    harness.get_by_label("DISPATCH TICKET");
    // The page can leave for a window of its own; the main window then
    // goes back to what was under it.
    click(&mut harness, "Back");
    click(&mut harness, "Pop out");
    assert!(actions(&harness).contains(&AppAction::PopOutDispatch));
    assert!(harness.state().core().settings().dispatch_window.is_some());
    assert_ne!(harness.state().core().view(), View::Dispatch);
}

