            settings,
            views,
        })),
        Clock::at(1),
    );
    assert_eq!(core.active_space(), SpaceId::GLOBAL);
    assert_eq!(core.working_sets(), &[set][..]);
    assert_eq!(core.project_space(stray_id), Some(SpaceId::DEFAULT));
    assert_eq!(core.view(), View::Board(pb.id));
}

