        Some(HostStatus {
            last_activity: Some(output),
            ..exited(s.id, Some(0))
        })
    });
    let id = ids[0];
    let e = core.dispatch(AppAction::ReturnToSession(id), Clock::at(60_000));
    assert!(
        matches!(&e[0], Effect::Save(w) if w.sessions[0].last_seen == output),
        "{e:?}"
    );
