    );
    // Adding to a set: once, in the first free spot; twice is once.
    let command = PinTarget::Session(ids[1]);
    core.dispatch(
        AppAction::AddToWorkingSet {
            set: first,
            target: command.clone(),
            columns: 24,
        },
