        .collect();
    assert_eq!(
        rects[0],
        GridRect {
            x: 0,
            y: 0,
            w: 10,
            h: 8
        }
    );
    assert_eq!(
        rects[1],
        GridRect {
            x: 10,
            y: 0,
            w: 10,
            h: 7
        }
    );
    // A target that does not exist is not added; a file needs its project.
    let e = core.dispatch(
