                tasks: vec!["shell".into()],
                wakeups: vec![],
            },
        );
        core.dispatch(AppAction::HostListed(vec![]), Clock::at(6_000));
        assert!(!core.is_running(reviewer));
        missing(&mut core, run, past_grace(5_000));
