// --- rule sets: sessions active in the last N hours

const HOUR_MS: u64 = 3_600_000;

fn recent_set(core: &mut AppCore, hours: u32, at: u64) -> SetId {
    core.dispatch(
        AppAction::NewRuleSet {
            name: None,
            rule: SetRule::Recent { hours },
        },
