// --- the web page

const CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";

/// A page request answered by the connection thread alone.
fn page(port: &Port, path: &str) -> Resp {
    exchange(port.addr, &port.client, "GET", path, &[], "").expect("page")
}

/// Pair as a browser does: `transport: cookie`, the reply and the
/// cookie it set (`name=value`).
fn pair_browser(port: &mut Port, code: &str, scope: Scope) -> (Resp, String) {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    let body = serde_json::json!({
        "code": code, "device_name": "Safari on iPhone", "spki_sha256": spki, "transport": "cookie",
    });
    let resp = call_with(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(resp.status, 200, "{}", resp.body);
    let set = resp.header("set-cookie").expect("a cookie").to_owned();
    let cookie = set.split(';').next().unwrap().to_owned();
    (resp, cookie)
}

fn json(resp: &Resp) -> serde_json::Value {
    serde_json::from_str(&resp.body).unwrap_or_else(|e| panic!("{e}: {}", resp.body))
}

#[test]
fn the_three_pages_are_served_to_a_stranger_with_their_headers() {
    let port = port();
    for (path, kind) in [
        ("/", "text/html; charset=utf-8"),
        ("/app.js", "text/javascript; charset=utf-8"),
        ("/app.css", "text/css; charset=utf-8"),
    ] {
        let r = page(&port, path);
        assert_eq!(r.status, 200, "{path}");
        assert_eq!(r.header("content-type"), Some(kind), "{path}");
        assert_eq!(r.header("content-security-policy"), Some(CSP), "{path}");
        assert_eq!(r.header("cache-control"), Some("no-store"));
        assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
        assert_eq!(r.header("referrer-policy"), Some("no-referrer"));
        assert_eq!(r.header("connection"), Some("close"));
        assert!(!r.body.is_empty(), "{path}");
    }
    // A query is ignored and never echoed.
    let r = page(&port, "/?code=SECRET123");
    assert_eq!(r.status, 200);
    assert!(!r.body.contains("SECRET123"));
}

#[test]
fn everything_else_outside_the_api_is_still_the_json_404() {
    let mut port = port();
    for (method, path) in [
        ("GET", "/favicon.ico"),
        ("POST", "/"),
        ("GET", "/api"),
        ("GET", "/app.js/"),
    ] {
        let r = call_with(&mut port, method, path, &[], "");
        assert_eq!(r.status, 404, "{method} {path}");
        assert_eq!(code(&json(&r)), "not_found");
        assert_eq!(r.header("content-type"), Some("application/json"));
        assert_eq!(r.header("cache-control"), Some("no-store"));
        assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
    }
}

#[test]
fn the_embedded_page_asks_only_for_what_the_host_serves() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let project = port.app.core().projects().first().unwrap().id.0.to_string();
    let token = pair(&mut port, "ABCD2345", Scope::Control, "Pad");
    let html = page(&port, "/").body;
    let js = page(&port, "/app.js").body;

    // index.html: every src and href is a served path or data:.
    for attr in ["src=\"", "href=\""] {
        for part in html.split(attr).skip(1) {
            let value = part.split('"').next().unwrap();
            assert!(
                value.starts_with("data:") || page(&port, value).status == 200,
                "{value}"
            );
        }
    }
    // No inline script, handler or style: the CSP would refuse them.
    for script in html.split("<script").skip(1) {
        assert!(script.split('>').next().unwrap().contains("src="));
    }
    assert!(!html.contains(" on") || !html.contains("onclick="));
    for forbidden in ["onclick=", "onload=", "onerror=", "onsubmit=", "style=", "<style"] {
        assert!(!html.contains(forbidden), "{forbidden}");
    }
    for forbidden in ["innerHTML", "outerHTML", "eval(", "document.write", "insertAdjacentHTML"] {
        assert!(!js.contains(forbidden), "{forbidden}");
    }

    // app.js: every /api/v1 string in its table answers something but
    // the port's "no such route".
    let table = js
        .split("const API = {")
        .nth(1)
        .and_then(|t| t.split("};").next())
        .unwrap();
    let mut seen = 0;
    for line in table.lines() {
        let Some(path) = line.split('\'').nth(1).filter(|p| p.starts_with("/api/v1/")) else {
            continue;
        };
        seen += 1;
        let path = path
            .replace("projects/{id}", &format!("projects/{project}"))
            .replace("sessions/{id}", &format!("sessions/{session}"));
        let method = if path.ends_with("/pair") || path.ends_with("/send") {
            "POST"
        } else {
            "GET"
        };
        let (status, reply) = call(&mut port, method, &path, Some(&token), "{}");
        let message = reply["error"]["message"].as_str().unwrap_or("");
        assert_ne!(message, "not available on this port", "{method} {path}");
        assert_ne!(message, "no such endpoint", "{method} {path}");
        assert_ne!(status, 0);
    }
    assert!(seen >= 9, "the table was read: {seen}");
}

#[test]
fn a_browser_pairs_into_a_cookie_named_for_the_host_and_reads_with_it() {
    let mut port = port();
    let (resp, cookie) = pair_browser(&mut port, "ABCD2345", Scope::Read);
    let body = json(&resp);
    assert!(body["body"].get("token").is_none(), "{body}");
    let server_id = body["body"]["server_id"].as_str().unwrap().to_owned();
    let set = resp.header("set-cookie").unwrap();
    assert!(set.starts_with(&format!("__Host-sb-{server_id}=")), "{set}");
    for attr in ["HttpOnly", "Secure", "SameSite=Strict", "Path=/"] {
        assert!(set.contains(attr), "{attr} in {set}");
    }
    assert!(!set.contains("Domain"), "{set}");

    let me = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(me.status, 200, "{}", me.body);
    let me = json(&me);
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["server_id"], server_id.as_str());
    let id = port.app.core().devices()[0].id;
    port.app.dispatch(AppAction::SetDeviceScope {
        device: id,
        scope: Scope::Control,
    });
    let me = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(json(&me)["body"]["scope"], "control");

    // A cookie under the fixed name authenticates nothing.
    let token = cookie.split_once('=').unwrap().1.to_owned();
    let fixed = format!("__Host-sb={token}");
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &fixed)], "");
    assert_eq!(r.status, 401);

    // Revoked: the same 401 an unknown token gets, and /info still
    // answers with the identity the page stored.
    port.app.dispatch(AppAction::RevokeDevice(id));
    let r = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!((r.status, code(&json(&r))), (401, "unauthorized"));
    let (_, info) = get(&mut port, "/api/v1/info", None);
    assert_eq!(info["body"]["server_id"], server_id.as_str());
    assert_eq!(
        info["body"]["spki_sha256"],
        port.remote.state().identity.as_ref().unwrap().spki_sha256.as_str()
    );
}

#[test]
fn a_native_pair_is_unchanged_and_a_rotated_key_is_a_different_key() {
    let mut port = port();
    port.app.dispatch(AppAction::OpenPairing {
        code: "ABCD2345".into(),
        scope: Scope::Read,
    });
    let spki = port.remote.state().identity.as_ref().unwrap().spki_sha256.clone();
    let body = serde_json::json!({ "code": "ABCD2345", "device_name": "Pad", "spki_sha256": spki });
    let r = call_with(&mut port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(r.status, 200);
    assert!(r.header("set-cookie").is_none());
    assert!(json(&r)["body"]["token"].is_string());

    let (old, _) = remote::make_identity(None, "Old", Listen::default()).unwrap();
    let (again, _) = remote::make_identity(Some(old.server_id), "Old", Listen::default()).unwrap();
    assert_eq!(old.server_id, again.server_id);
    assert_ne!(old.spki_sha256, again.spki_sha256);
}

#[test]
fn two_hosts_on_one_address_keep_their_own_cookies() {
    let mut a = port();
    let mut b = port();
    let (_, cookie_a) = pair_browser(&mut a, "ABCD2345", Scope::Read);
    let (_, cookie_b) = pair_browser(&mut b, "WXYZ6789", Scope::Read);
    assert_ne!(
        cookie_a.split_once('=').unwrap().0,
        cookie_b.split_once('=').unwrap().0
    );
    let both = format!("{cookie_a}; {cookie_b}");
    for (port, name) in [(&mut a, "a"), (&mut b, "b")] {
        let r = call_with(port, "GET", "/api/v1/me", &[("Cookie", &both)], "");
        assert_eq!(r.status, 200, "{name}: {}", r.body);
    }
    let r = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &cookie_b)], "");
    assert_eq!(r.status, 401, "the other host's cookie is not this host's");
}

#[test]
fn a_cookie_write_must_come_from_the_pages_own_origin() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let (_, cookie) = pair_browser(&mut port, "ABCD2345", Scope::Control);
    running(&mut port, &session, "\u{276f} ");
    let send = format!("/api/v1/sessions/{session}/send");
    let body = r#"{"op":"tx1","text":"hello"}"#;
    let c = ("Cookie", cookie.as_str());

    let r = call_with(&mut port, "POST", &send, &[c], body);
    assert_eq!((r.status, code(&json(&r))), (403, "origin"));
    let r = call_with(&mut port, "POST", &send, &[c, ("Origin", "https://localhost:9")], body);
    assert_eq!((r.status, code(&json(&r))), (403, "origin"));
    assert!(port.host.state().written.is_empty());
    let r = call_with(&mut port, "POST", &send, &[c, ("Origin", "https://localhost")], body);
    assert_eq!(r.status, 200, "{}", r.body);
    assert_eq!(port.host.state().written.len(), 1);

    // A bearer needs none: a native client sends no Origin.
    let token = pair(&mut port, "WXYZ6789", Scope::Control, "Pad");
    let (status, _) = call(&mut port, "POST", &send, Some(&token), r#"{"op":"tx2","text":"again"}"#);
    assert_eq!(status, 200);

    // A cookie upgrade is a write too.
    let upgrade = |origin: Option<&str>, port: &mut Port| {
        let mut h = vec![
            c,
            ("Upgrade", "websocket"),
            ("Connection", "Upgrade"),
            ("Sec-WebSocket-Key", "dGhlIHNhbXBsZSBub25jZQ=="),
            ("Sec-WebSocket-Version", "13"),
        ];
        if let Some(o) = origin {
            h.push(("Origin", o));
        }
        call_with(port, "GET", "/api/v1/events", &h, "").status
    };
    assert_eq!(upgrade(Some("https://evil.example"), &mut port), 403);
    assert_eq!(upgrade(None, &mut port), 403);
    assert_eq!(upgrade(Some("https://localhost"), &mut port), 101);
}

#[test]
fn a_page_closes_its_connection_and_pages_have_their_own_window() {
    let mut port = port();
    for _ in 0..MAX_UNAUTHENTICATED + 1 {
        assert_eq!(page(&port, "/").status, 200);
    }
    // Four stalled strangers still fill the pool for a page request.
    let strangers: Vec<TcpStream> = (0..MAX_UNAUTHENTICATED)
        .map(|_| TcpStream::connect(port.addr).expect("connect"))
        .collect();
    std::thread::sleep(Duration::from_millis(100));
    assert!(
        exchange(port.addr, &port.client, "GET", "/", &[], "").is_err(),
        "the fifth is closed at accept"
    );
    drop(strangers);
    std::thread::sleep(Duration::from_millis(100));

    // The window is 120 a minute; /info and /pair keep their own.
    let mut statuses = Vec::new();
    for _ in 0..121 {
        statuses.push(page(&port, "/app.css").status);
    }
    assert!(statuses.iter().filter(|s| **s == 429).count() >= 1, "{statuses:?}");
    assert_eq!(statuses.last(), Some(&429));
    let (status, _) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200);
    let (status, _) = call(&mut port, "POST", "/api/v1/pair", None, "{}");
    assert_eq!(status, 403, "pair is not in the page window");
}

